#!/usr/bin/env python3
"""Caruso baseline throughput campaign for the 360-SATC paper.

Runs MUC, PC, AUC, and 360-ST on four 4K ERP videos with the same H.264,
H.265/HEVC, and AV1 NVENC P4 backend at 12 and 35 Mbit/s.

Measurement boundary: unpaced local sender processing only. No WebRTC, Mininet,
receiver, HMD, frame-rate limiter, or intentional frame dropping. Each run uses
240 warm-up frames followed by 1200 measured completed frames.

A single real recorded head-movement trace is selected deterministically from the
public 360-Degree Video Experiment Dataset shared.mat file and replayed identically
for all four contents. This controls viewport-motion workload across videos.
"""
from __future__ import annotations
import argparse, base64, csv, datetime as _dt, hashlib, io, json, math, os, pwd, re, shutil, statistics, subprocess, sys, tempfile, time, traceback, urllib.request, zipfile
from pathlib import Path
from typing import Any
import numpy as np

VERSION='Caruso_Baselines_4Videos_P4_v3_ALL_IN_ONE'
WIDTH,HEIGHT,FPS=4096,2048,60
WARMUP,MEASURED=240,1200
