SATC_PY_ABS = Path(os.environ.get("SATC_PYTHON", sys.executable))
INPUT_ROOT_ABS = Path(os.environ.get("SATC_PREPARED", 'data/prepared'))
FIXED_VIDEOS={
 'basketball':INPUT_ROOT_ABS/'basketball_4096x2048_60fps.mp4',
 'rollercoaster':INPUT_ROOT_ABS/'rollercoaster_4096x2048_60fps.mp4',
 'ballet':INPUT_ROOT_ABS/'ballet_4096x2048_60fps.mp4',
}
CODECS=('h264','hevc','av1'); RATES=(12,35); METHODS=('muc','pc','auc','360st')
