BASELINE_PRODUCER = '#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse, csv, json, math, os, queue, selectors, signal, struct, subprocess, sys, threading, time, traceback\nfrom pathlib import Path\nimport numpy as np\nfrom shared_frame import SharedFrame\n\nW,H,FPS=4096,2048,60\nFRAME_BYTES=W*H*3//2\nPERIOD_NS=1_000_000_000//FPS\nQUEUE_FRAMES=4\nNATIVE_IN=struct.Struct(\'<4sQIII\')\nNATIVE_OUT=struct.Struct(\'<4sQQQII\')\nGRID_R,GRID_C=5,9\nZONE_COUNTS_EQUIRECT_CENTER=(1,8,16,20)\nETA=np.array([0.4,0.3,0.2,0.1],dtype=np.float64)\nAREA=np.array(ZONE_COUNTS_EQUIRECT_CENTER,dtype=np.float64)/45.0\n\n\ndef read_exact(stream,n,timeout=60):\n    data=bytearray(n); view=memoryview(data); pos=0; deadline=time.monotonic()+timeout\n    with selectors.DefaultSelector() as sel:\n        sel.register(stream,selectors.EVENT_READ)\n        while pos<n:\n            remaining=deadline-time.monotonic()\n            if remaining<=0 or not sel.select(remaining): raise TimeoutError(f\'timed out at {pos}/{n}\')\n            k=stream.readinto(view[pos:])\n            if not k: raise EOFError(f\'EOF at {pos}/{n}\')\n            pos+=k\n    return bytes(data)\n\n\ndef write_all(stream,data):\n    view=memoryview(data)\n    while view:\n        n=stream.write(view)\n        if not n: raise BrokenPipeError(\'short write\')\n        view=view[n:]\n\n\ndef gamma_to_qp_delta(gamma):\n    # One-to-one mapping of the published 11 compression levels {0,10,...,100}\n    # to 11 signed NVENC QP-delta levels {-5,-4,...,+5}. 50% is neutral CBR.\n    g=int(round(float(gamma)/10.0))*10\n    g=max(0,min(100,g))\n    return np.int8(g//10-5)\n\n\ndef tile_zone_labels(center_row,center_col):\n    out=np.empty((GRID_R,GRID_C),dtype=np.uint8)\n    for r in range(GRID_R):\n        dr=abs(r-int(center_row))\n        for c in range(GRID_C):\n            raw=abs(c-int(center_col)); dc=min(raw,GRID_C-raw)  # ERP horizontal wrap\n            d=max(dr,dc)\n            out[r,c]=0 if d==0 else (1 if d==1 else (2 if d==2 else 3))\n    return out\n\n\ndef build_zone_block_maps(codec):\n    block={\'h264\':16,\'hevc\':32,\'av1\':64}[codec]\n    bh=(H+block-1)//block; bw=(W+block-1)//block\n    # Equal 5x9 logical grid, same as the 360-SATC evaluation grid.\n    xe=np.linspace(0,W,GRID_C+1,dtype=np.int64)\n    ye=np.linspace(0,H,GRID_R+1,dtype=np.int64)\n    x=np.minimum(np.arange(bw)*block+block//2,W-1)\n    y=np.minimum(np.arange(bh)*block+block//2,H-1)\n    tx=np.searchsorted(xe[1:],x,side=\'right\')\n    ty=np.searchsorted(ye[1:],y,side=\'right\')\n    maps={}\n    for cr in range(GRID_R):\n        for cc in range(GRID_C):\n            ztiles=tile_zone_labels(cr,cc)\n            maps[(cr,cc)]=np.ascontiguousarray(ztiles[ty[:,None],tx[None,:]])\n    return maps\n\n\ndef qmap_from_action(zone_map,gammas):\n    deltas=np.array([gamma_to_qp_delta(g) for g in gammas],dtype=np.int8)\n    return np.ascontiguousarray(deltas[zone_map])\n\n\ndef load_trace(path,total):\n    rows=[]\n    with Path(path).open(newline=\'\',encoding=\'utf-8\') as f:\n        for r in csv.DictReader(f):\n            rows.append((int(r[\'frame_id\']),int(r[\'tile_row\']),int(r[\'tile_col\']),float(r[\'yaw_deg\']),float(r[\'pitch_deg\']),float(r[\'roll_deg\'])))\n    if len(rows)<total: raise RuntimeError(f\'trace has {len(rows)} rows, need {total}\')\n    rows=rows[:total]\n    if [x[0] for x in rows] != list(range(total)): raise RuntimeError(\'trace frame IDs are not contiguous from zero\')\n    return rows\n\n\nclass Source:\n    def __init__(self,video,stop_evt,gate,warmup,total):\n        self.q=queue.Queue(QUEUE_FRAMES); self.stop=stop_evt; self.error=None; self.done=threading.Event()\n        self.gate=gate; self.warmup=warmup; self.total=total\n        cmd=[\'ffmpeg\',\'-nostdin\',\'-hide_banner\',\'-loglevel\',\'error\',\'-xerror\',\'-stream_loop\',\'-1\',\'-hwaccel\',\'cuda\',\'-hwaccel_output_format\',\'cuda\',\'-i\',str(video),\'-map\',\'0:v:0\',\'-an\',\'-sn\',\'-vf\',\'hwdownload,format=nv12\',\'-fps_mode\',\'passthrough\',\'-pix_fmt\',\'nv12\',\'-f\',\'rawvideo\',\'pipe:1\']\n        self.proc=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=sys.stderr,bufsize=0)\n        def work():\n            fid=0\n            try:\n                while not self.stop.is_set() and fid<self.total:\n                    if fid==self.warmup:\n                        while not self.gate.wait(.2):\n                            if self.stop.is_set(): return\n                    read_start=time.time_ns(); raw=read_exact(self.proc.stdout,FRAME_BYTES,30); available=time.time_ns()\n                    while not self.stop.is_set():\n                        try: self.q.put((fid,raw,read_start,available),timeout=.2); break\n                        except queue.Full: pass\n                    fid+=1\n            except BaseException:\n                if not self.stop.is_set(): self.error=traceback.format_exc()\n            finally: self.done.set()\n        self.thread=threading.Thread(target=work,name=\'source\',daemon=True); self.thread.start()\n    def close(self):\n        self.stop.set(); self.gate.set()\n        if self.proc.poll() is None: self.proc.terminate()\n        self.thread.join(3)\n        try: self.proc.wait(3)\n        except subprocess.TimeoutExpired: self.proc.kill(); self.proc.wait()\n\n\nclass SizeModel:\n    def __init__(self,budget_bytes):\n        self.budget=float(budget_bytes)\n        self.base=None\n        self.alpha=0.08\n    @staticmethod\n    def factor(gammas):\n        d=np.array([int(g)//10-5 for g in gammas],dtype=np.float64)\n        # Common QP-rate approximation: roughly one bit-rate halving per +6 QP.\n        qfactor=np.power(2.0,-d/6.0)\n        return float(np.dot(AREA,qfactor))\n    def update(self,actual_bytes,gammas):\n        f=max(self.factor(gammas),1e-9)\n        estimate=float(actual_bytes)/f\n        self.base=estimate if self.base is None else (1.0-self.alpha)*self.base+self.alpha*estimate\n    def predict(self,gammas):\n        b=self.base if self.base is not None else self.budget\n        return float(b*self.factor(gammas))\n\n\nclass Policy:\n    def __init__(self,method,budget_bytes):\n        self.method=method; self.budget=float(budget_bytes); self.model=SizeModel(budget_bytes)\n        self.last_action=(0,30,70,100) if method in (\'pc\',\'360st\') else ((100,100,100,100) if method==\'muc\' else (50,50,50,50))\n        self.actions360=[]\n        if method==\'360st\':\n            # Published action space is four simultaneous compression levels, each in {0,10,...,100}.\n            # Enforce viewport-quality ordering (inner zones no more compressed than outer zones).\n            for g1 in range(0,101,10):\n                for g2 in range(g1,101,10):\n                    for g3 in range(g2,101,10):\n                        for g4 in range(g3,101,10):\n                            a=(g1,g2,g3,g4)\n                            utility=float(np.dot(ETA,1.0-np.array(a,dtype=np.float64)/100.0))\n                            factor=SizeModel.factor(a)\n                            self.actions360.append((a,utility,factor))\n            self.actions360.sort(key=lambda x:(-x[1],x[2],x[0]))\n    def choose(self):\n        if self.method==\'muc\': return (100,100,100,100), self.model.predict((100,100,100,100))\n        if self.method==\'pc\': return (0,30,70,100), self.model.predict((0,30,70,100))\n        if self.method==\'auc\':\n            for g in range(0,101,10):\n                a=(g,g,g,g); pred=self.model.predict(a)\n                if pred<=self.budget: self.last_action=a; return a,pred\n            a=(100,100,100,100); self.last_action=a; return a,self.model.predict(a)\n        # 360-ST: maximize viewport-weighted quality over the published four-zone action space\n        # under the current frame budget, using the warmup-calibrated encoded-size model.\n        base=self.model.base if self.model.base is not None else self.budget\n        for a,utility,factor in self.actions360:\n            pred=base*factor\n            if pred<=self.budget:\n                self.last_action=a; return a,float(pred)\n        a=(100,100,100,100); self.last_action=a; return a,self.model.predict(a)\n    def observe(self,actual_bytes,action):\n        self.model.update(actual_bytes,action)\n\n\ndef map_self_test():\n    assert [int(gamma_to_qp_delta(g)) for g in range(0,101,10)] == list(range(-5,6))\n    z=tile_zone_labels(2,4)\n    counts=tuple(int((z==i).sum()) for i in range(4))\n    assert counts==ZONE_COUNTS_EQUIRECT_CENTER, counts\n    for codec in (\'h264\',\'hevc\',\'av1\'):\n        maps=build_zone_block_maps(codec)\n        q=qmap_from_action(maps[(2,4)],(0,30,70,100))\n        assert q.dtype==np.int8 and q.flags[\'C_CONTIGUOUS\']\n        assert int(q.min())==-5 and int(q.max())==5\n    print(\'PASS: 5x9 zones, 1/8/16/20 center counts, 11-level QP mapping, and codec QP maps.\')\n    return 0\n\n\ndef main():\n    ap=argparse.ArgumentParser()\n    ap.add_argument(\'--map-self-test\',action=\'store_true\')\n    ap.add_argument(\'--video\',type=Path); ap.add_argument(\'--encoder\',type=Path)\n    ap.add_argument(\'--codec\',choices=[\'h264\',\'hevc\',\'av1\']); ap.add_argument(\'--method\',choices=[\'muc\',\'pc\',\'auc\',\'360st\'])\n    ap.add_argument(\'--trace\',type=Path); ap.add_argument(\'--output-dir\',type=Path)\n    ap.add_argument(\'--target-bitrate-bps\',type=int); ap.add_argument(\'--benchmark-frames\',type=int,default=1200); ap.add_argument(\'--benchmark-warmup\',type=int,default=240)\n    args=ap.parse_args()\n    if args.map_self_test: return map_self_test()\n    for name in (\'video\',\'encoder\',\'codec\',\'method\',\'trace\',\'output_dir\',\'target_bitrate_bps\'):\n        if getattr(args,name) is None: ap.error(f\'--{name.replace("_","-")} is required\')\n    args.output_dir.mkdir(parents=True,exist_ok=True)\n    warm=args.benchmark_warmup; measured=args.benchmark_frames; total=warm+measured\n    trace=load_trace(args.trace,total)\n    zone_maps=build_zone_block_maps(args.codec)\n    budget=float(args.target_bitrate_bps)/(8.0*FPS)\n    policy=Policy(args.method,budget)\n    stop_evt=threading.Event(); gate=threading.Event()\n    signal.signal(signal.SIGINT,lambda *_: stop_evt.set()); signal.signal(signal.SIGTERM,lambda *_: stop_evt.set())\n    shared=SharedFrame(FRAME_BYTES)\n    log=(args.output_dir/\'nvenc_dynamic.log\').open(\'w\',encoding=\'utf-8\',buffering=1)\n    enc=subprocess.Popen([str(args.encoder),args.codec,str(args.target_bitrate_bps),str(shared.fd)],pass_fds=(shared.fd,),stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=log,bufsize=0)\n    if read_exact(enc.stdout,4)!=b\'RDY1\': raise RuntimeError(\'NVENC bridge not ready\')\n    source=Source(args.video,stop_evt,gate,warm,total)\n    events=(args.output_dir/\'baseline_events.csv\').open(\'w\',newline=\'\',encoding=\'utf-8\',buffering=1)\n    fields=[\'frame_id\',\'source_read_start_unix_ns\',\'source_available_unix_ns\',\'tile_row\',\'tile_col\',\'yaw_deg\',\'pitch_deg\',\'roll_deg\',\'method\',\'gamma_z1\',\'gamma_z2\',\'gamma_z3\',\'gamma_z4\',\'qp_min\',\'qp_max\',\'policy_map_ms\',\'predicted_bytes\',\'encode_submit_unix_ns\',\'encode_begin_mono_ns\',\'encode_end_mono_ns\',\'completion_unix_ns\',\'target_bitrate_bps\',\'applied_bitrate_bps\',\'encoded_bytes\',\'budget_bytes\',\'budget_fit\']\n    writer=csv.DictWriter(events,fieldnames=fields); writer.writeheader()\n    measured_start=measured_end=None; sizes=[]; actions=[]; fits=[]; policy_times=[]; centers=[]; expected=0\n    qcache={}\n    try:\n        while not stop_evt.is_set():\n            try: item=source.q.get(timeout=.2)\n            except queue.Empty:\n                if source.error: raise RuntimeError(source.error)\n                if source.done.is_set(): break\n                continue\n            fid,raw,read_start,available=item\n            if fid!=expected: raise RuntimeError(f\'source ID gap {expected}->{fid}\')\n            _,tr,tc,yaw,pitch,roll=trace[fid]\n            p0=time.monotonic_ns(); action,pred=policy.choose()\n            key=(tr,tc,action)\n            qp=qcache.get(key)\n            if qp is None:\n                qp=qmap_from_action(zone_maps[(tr,tc)],action); qcache[key]=qp\n            p1=time.monotonic_ns(); map_ms=(p1-p0)/1e6\n            submit=time.time_ns(); shared.copy_from(raw)\n            write_all(enc.stdin,NATIVE_IN.pack(b\'FRM2\',fid,len(raw),qp.nbytes,args.target_bitrate_bps)); write_all(enc.stdin,qp.tobytes())\n            hdr=read_exact(enc.stdout,NATIVE_OUT.size); magic,oid,beg,end,size,applied=NATIVE_OUT.unpack(hdr)\n            if magic!=b\'AU02\' or oid!=fid: raise RuntimeError(\'NVENC output identity mismatch\')\n            _packet=read_exact(enc.stdout,size); complete=time.time_ns()\n            policy.observe(size,action)\n            fit=size<=budget\n            writer.writerow({\'frame_id\':fid,\'source_read_start_unix_ns\':read_start,\'source_available_unix_ns\':available,\'tile_row\':tr,\'tile_col\':tc,\'yaw_deg\':yaw,\'pitch_deg\':pitch,\'roll_deg\':roll,\'method\':args.method,\'gamma_z1\':action[0],\'gamma_z2\':action[1],\'gamma_z3\':action[2],\'gamma_z4\':action[3],\'qp_min\':int(qp.min()),\'qp_max\':int(qp.max()),\'policy_map_ms\':map_ms,\'predicted_bytes\':pred,\'encode_submit_unix_ns\':submit,\'encode_begin_mono_ns\':beg,\'encode_end_mono_ns\':end,\'completion_unix_ns\':complete,\'target_bitrate_bps\':args.target_bitrate_bps,\'applied_bitrate_bps\':applied,\'encoded_bytes\':size,\'budget_bytes\':budget,\'budget_fit\':int(fit)})\n            if fid==warm-1:\n                measured_start=time.monotonic_ns(); gate.set()\n            if fid>=warm:\n                sizes.append(size); actions.append(action); fits.append(bool(fit)); policy_times.append(map_ms); centers.append((tr,tc))\n            if fid==total-1:\n                measured_end=time.monotonic_ns(); break\n            expected+=1\n        expected+=1\n    finally:\n        stop_evt.set(); gate.set(); events.close(); source.close()\n        try: enc.stdin.close()\n        except Exception: pass\n        try: enc.wait(5)\n        except subprocess.TimeoutExpired: enc.terminate(); enc.wait(3)\n        shared.close(); log.close()\n    if measured_start is None or measured_end is None or len(sizes)!=measured:\n        raise RuntimeError(f\'benchmark incomplete: measured outputs={len(sizes)}/{measured}\')\n    elapsed=(measured_end-measured_start)/1e9; proc_fps=measured/elapsed\n    mean_bytes=float(np.mean(sizes)); media_mbps=mean_bytes*8*FPS/1e6\n    sustainable=float(args.target_bitrate_bps)/(8.0*mean_bytes) if mean_bytes>0 else None\n    arr=np.array(actions,dtype=np.float64)\n    result={\'method\':args.method,\'codec\':args.codec,\'target_mbps\':args.target_bitrate_bps/1e6,\'measured_frames\':measured,\'warmup_frames\':warm,\'elapsed_seconds\':elapsed,\'fps\':proc_fps,\'at_least_60\':proc_fps>=60.0,\'frame_drops\':0,\'mean_encoded_bytes\':mean_bytes,\'actual_media_bitrate_mbps\':media_mbps,\'bandwidth_sustainable_fps\':sustainable,\'budget_fit_fraction\':float(np.mean(fits)),\'mean_policy_map_ms\':float(np.mean(policy_times)),\'p95_policy_map_ms\':float(np.percentile(policy_times,95)),\'mean_gamma_z1\':float(arr[:,0].mean()),\'mean_gamma_z2\':float(arr[:,1].mean()),\'mean_gamma_z3\':float(arr[:,2].mean()),\'mean_gamma_z4\':float(arr[:,3].mean()),\'unique_viewport_centers\':len(set(centers)),\'qp_mapping\':\'Gamma 0..100 in steps of 10 -> NVENC QP delta -5..+5\',\'timing_start\':\'after final warmup AU, before opening source gate for any measured frame\',\'timing_end\':\'after final measured AU returned by NVENC\'}\n    (args.output_dir/\'benchmark.json\').write_text(json.dumps(result,indent=2)+\'\\n\',encoding=\'utf-8\')\n    print(json.dumps(result),file=sys.stderr,flush=True)\n    return 0\n\nif __name__==\'__main__\': raise SystemExit(main())\n'


def dump(path,obj):
    path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(obj,indent=2,sort_keys=False)+'\n',encoding='utf-8')

def sha256(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
    return h.hexdigest()

def command(cmd,log=None,env=None,check=True,timeout=None,cwd=None):
    p=subprocess.run([str(x) for x in cmd],text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,env=env,timeout=timeout,cwd=cwd)
    if log is not None:
        Path(log).parent.mkdir(parents=True,exist_ok=True); Path(log).write_text(p.stdout or '',encoding='utf-8')
    if check and p.returncode: raise RuntimeError(f"Command failed ({p.returncode}): {' '.join(map(str,cmd))}\n{(p.stdout or '')[-6000:]}")
    return p

def extract_payload(code):
    import zlib
    raw=zlib.decompress(base64.b85decode(_PAYLOAD_B85.encode('ascii')))
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        bad=[n for n in z.namelist() if Path(n).is_absolute() or '..' in Path(n).parts]
        if bad: raise RuntimeError(f'Unsafe embedded payload members: {bad}')
        z.extractall(code)
    (code/'baseline_producer.py').write_text(BASELINE_PRODUCER,encoding='utf-8')

def real_user_home():
    user=os.environ.get('SUDO_USER') or os.environ.get('SATC_REAL_USER')
    if user and user!='root': return user,Path(pwd.getpwnam(user).pw_dir)
    try: return 'mininet-ovs',Path(pwd.getpwnam('mininet-ovs').pw_dir)
    except KeyError:
        pw=pwd.getpwuid(os.getuid()); return pw.pw_name,Path(pw.pw_dir)

def ffprobe(path):
    p=command(['ffprobe','-v','error','-select_streams','v:0','-show_entries','stream=codec_name,width,height,r_frame_rate,avg_frame_rate,nb_frames,duration','-of','json',str(path)])
    d=json.loads(p.stdout); 
    if not d.get('streams'): raise RuntimeError(f'No video stream: {path}')
    return d['streams'][0]

def rate_float(s):
    if not s or s=='0/0': return 0.0
    a,b=s.split('/') if '/' in s else (s,'1'); return float(a)/float(b)

def base_env(root):
    env=os.environ.copy(); env.update({'PYTHONUNBUFFERED':'1','OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'2','MKL_NUM_THREADS':'2'}); return env

def build_encoder(root,code):
    build=root/'build'
    command(['cmake','-S',str(code),'-B',str(build),f'-DSDK_TOP={SDK_ABS}','-DCMAKE_BUILD_TYPE=Release'],root/'build_configure.log')
    command(['cmake','--build',str(build),'-j',str(min(4,os.cpu_count() or 2))],root/'build_compile.log')
    enc=build/'nvenc_dynamic'
    if not enc.is_file(): raise RuntimeError('NVENC bridge did not build')
    return enc


def walk_limited(root,max_depth=7):
    root=Path(root)
    if not root.exists(): return
    root_depth=len(root.parts)
    skip={'.git','.cache','venv','venvs','node_modules','Library','site-packages'}
    for cur,dirs,files in os.walk(root):
        d=Path(cur)
        depth=len(d.parts)-root_depth
        dirs[:]=[x for x in dirs if x not in skip and not x.startswith('.Trash')]
        if depth>=max_depth: dirs[:]=[]
        yield d,files

def discover_london(home,override=None):
    if override:
        p=Path(override).expanduser().resolve()
        if not p.is_file(): raise RuntimeError(f'--london-video does not exist: {p}')
        candidates=[p]
    else:
        candidates=[]
        for root in (home/'Downloads',home/'360SATC_NVENC'):
            for d,files in walk_limited(root,8) or []:
                for name in files:
                    low=name.lower()
                    if Path(name).suffix.lower() not in ('.mp4','.mkv','.webm','.mov','.m4v'): continue
                    if 'london' in low or ('tower' in low and 'bridge' in low): candidates.append(d/name)
        # newest first, but exact geometry/rate dominates below
        candidates=sorted(set(candidates),key=lambda p:p.stat().st_mtime if p.exists() else 0,reverse=True)
    audited=[]
    best=None; bestscore=-1
    for p in candidates[:120]:
        try:
            m=ffprobe(p); w=int(m.get('width',0)); h=int(m.get('height',0)); fr=rate_float(m.get('avg_frame_rate') or m.get('r_frame_rate')); dur=float(m.get('duration') or 0)
            score=(1000 if (w,h)==(WIDTH,HEIGHT) else 0)+(1000 if abs(fr-FPS)<0.01 else 0)+(100 if dur>=24 else 0)
            audited.append({'path':str(p),'width':w,'height':h,'fps':fr,'duration':dur,'score':score})
            if score>bestscore: bestscore=score; best=p
        except Exception as e: audited.append({'path':str(p),'error':str(e)})
    if best is None or bestscore<2100:
        raise RuntimeError('Could not auto-discover an exact 4096x2048 ~60 FPS London/Tower Bridge input. Re-run with --london-video /exact/path.mp4. Candidates: '+json.dumps(audited[:20]))
    return best,audited


def find_shared_mat(home,root,override=None):
    if override:
        p=Path(override).expanduser().resolve()
        if not p.is_file(): raise RuntimeError(f'--shared-mat does not exist: {p}')
        return p,{'source':'override','path':str(p)}
    mats=[]
    for p in [home/'snap/firefox/common/shared.mat',home/'Downloads/shared.mat']:
        if p.is_file(): mats.append(p)
    for base in (home/'snap/firefox/common',home/'Downloads'):
        if base.is_dir():
            mats += list(base.glob('shared*.mat'))
    if mats:
        p=max(set(mats),key=lambda x:x.stat().st_mtime); return p,{'source':'existing_mat','path':str(p)}
    zips=[]
    for base in (home/'snap/firefox/common',home/'Downloads'):
        if base.is_dir(): zips += list(base.glob('shared*.zip'))
    if not zips:
        z=root/'shared.zip'
        try:
            urllib.request.urlretrieve('https://albara.ramli.net/research/360/download/shared.zip',z)
            zips=[z]
        except Exception as e:
            raise RuntimeError('shared.mat/shared*.zip not found locally and public dataset download failed: '+repr(e))
    z=max(set(zips),key=lambda x:x.stat().st_mtime)
    with zipfile.ZipFile(z) as f:
        names=[n for n in f.namelist() if Path(n).name.lower()=='shared.mat']
        if not names: raise RuntimeError(f'No shared.mat inside {z}')
        out=root/'trace_source'/'shared.mat'; out.parent.mkdir(parents=True,exist_ok=True)
        with f.open(names[0]) as src,out.open('wb') as dst: shutil.copyfileobj(src,dst)
    return out,{'source':'zip','zip':str(z),'member':names[0],'path':str(out)}


def _numeric_trace_candidate(a):
    try: arr=np.asarray(a,dtype=np.float64)
    except Exception: return None
    if arr.ndim!=2: return None
    if arr.shape[1]==4: pass
    elif arr.shape[0]==4: arr=arr.T
    else: return None
    if not 50<=arr.shape[0]<=2000 or not np.isfinite(arr).all(): return None
    t=arr[:,0]
    if np.ptp(t)<15 or np.ptp(t)>120: return None
    if np.mean(np.diff(t)>=-1e-9)<0.98: return None
    ang=arr[:,1:]
    if np.nanmax(np.abs(ang))>720 or float(np.std(ang))<0.05: return None
    return arr

def extract_trace_candidates(mat_path):
    try:
        import scipy.io
    except Exception as e: raise RuntimeError('scipy is required to read shared.mat in the SATC environment: '+repr(e))
    try:
        d=scipy.io.loadmat(str(mat_path),struct_as_record=False,squeeze_me=True)
    except NotImplementedError:
        raise RuntimeError('shared.mat is MATLAB v7.3/HDF5; this runner currently expects scipy-readable MAT format.')
    found=[]; seen=set()
    def visit(obj,path,depth=0):
        if depth>10: return
        oid=id(obj)
        if oid in seen: return
        seen.add(oid)
        cand=_numeric_trace_candidate(obj)
        if cand is not None:
            dt=np.diff(cand[:,0]); dy=np.diff(np.unwrap(np.deg2rad(cand[:,1]))); dx=np.diff(cand[:,2])
            valid=dt>1e-6
            activity=float(np.median((np.abs(np.rad2deg(dy[valid]))+np.abs(dx[valid]))/dt[valid])) if valid.any() else 0.0
            found.append((path,cand,activity)); return
        if isinstance(obj,dict):
            for k,v in obj.items():
                if str(k).startswith('__'): continue
                visit(v,f'{path}.{k}',depth+1)
        elif isinstance(obj,np.ndarray) and obj.dtype==object:
            for idx,v in np.ndenumerate(obj): visit(v,f'{path}{idx}',depth+1)
        elif isinstance(obj,np.ndarray) and obj.dtype.names:
            for name in obj.dtype.names: visit(obj[name],f'{path}.{name}',depth+1)
        elif hasattr(obj,'_fieldnames'):
            # Also recognize structures storing time/x/y/z as separate vectors.
            names=list(getattr(obj,'_fieldnames') or [])
            lmap={n.lower():n for n in names}
            tname=next((lmap[k] for k in ('time','t','timestamp') if k in lmap),None)
            xname=lmap.get('x'); yname=lmap.get('y'); zname=lmap.get('z')
            if tname and xname and yname and zname:
                try:
                    t=np.ravel(np.asarray(getattr(obj,tname),dtype=float)); x=np.ravel(np.asarray(getattr(obj,xname),dtype=float)); y=np.ravel(np.asarray(getattr(obj,yname),dtype=float)); z=np.ravel(np.asarray(getattr(obj,zname),dtype=float))
                    if len(t)==len(x)==len(y)==len(z):
                        c=_numeric_trace_candidate(np.column_stack([t,y,x,z]))
                        if c is not None: found.append((path+'[fields]',c,0.0))
                except Exception: pass
            for n in names: visit(getattr(obj,n),f'{path}.{n}',depth+1)
    visit(d,'root')
    # Deduplicate by hash of rounded content; sort path for deterministic index semantics.
    uniq={}
    for path,a,activity in found:
        key=hashlib.sha256(np.round(a,6).tobytes()).hexdigest()
        uniq.setdefault(key,(path,a,activity))
    return sorted(uniq.values(),key=lambda x:x[0])


def prepare_common_trace(mat_path,out_csv,trace_index=0,total=WARMUP+MEASURED):
    cand=extract_trace_candidates(mat_path)
    if not cand: raise RuntimeError(f'No valid Nx4 [time,Y,X,Z] head traces found in {mat_path}')
    idx=int(trace_index)%len(cand); path,a,activity=cand[idx]
    t=a[:,0].astype(float); t=t-t[0]
    # sort and remove duplicate time samples
    order=np.argsort(t,kind='stable'); t=t[order]; a=a[order]
    keep=np.r_[True,np.diff(t)>1e-9]; t=t[keep]; a=a[keep]
    need=(total-1)/FPS
    if t[-1]<need: raise RuntimeError(f'Selected trace duration {t[-1]:.3f} s is shorter than required {need:.3f} s')
    tf=np.arange(total,dtype=float)/FPS
    yaw_unwrap=np.unwrap(np.deg2rad(a[:,1]))
    yaw=np.rad2deg(np.interp(tf,t,yaw_unwrap)); yaw=((yaw+180)%360)-180
    pitch=np.interp(tf,t,a[:,2]); roll=np.interp(tf,t,a[:,3])
    # Dataset convention: col2=Y(yaw), col3=X(pitch), col4=Z(roll).
    cols=((yaw+180.0)/360.0*9.0).astype(int)%9
    pclip=np.clip(pitch,-90.0,90.0)
    rows=np.rint((90.0-pclip)/180.0*4.0).astype(int); rows=np.clip(rows,0,4)
    with out_csv.open('w',newline='',encoding='utf-8') as f:
        w=csv.writer(f); w.writerow(['frame_id','time_s','yaw_deg','pitch_deg','roll_deg','tile_row','tile_col'])
        for i in range(total): w.writerow([i,f'{tf[i]:.9f}',f'{yaw[i]:.9f}',f'{pitch[i]:.9f}',f'{roll[i]:.9f}',int(rows[i]),int(cols[i])])
    inventory=[]
    for j,(p,arr,act) in enumerate(cand): inventory.append({'index':j,'path':p,'samples':int(arr.shape[0]),'duration_s':float(arr[-1,0]-arr[0,0]),'activity_deg_per_s':float(act)})
    return {'mat_path':str(mat_path),'mat_sha256':sha256(mat_path),'candidate_count':len(cand),'selected_index':idx,'selected_path':path,'selected_samples':int(a.shape[0]),'selected_duration_s':float(t[-1]),'selected_activity_deg_per_s':float(activity),'reuse_policy':'same recorded trace replayed for all four videos','interpolation':'angle trace interpolated to 60 Hz; yaw unwrapped before interpolation','dataset_columns':'time, Y(yaw), X(pitch), Z(roll)','inventory':inventory}


def validate_video(path):
    m=ffprobe(path); w=int(m['width']); h=int(m['height']); fr=rate_float(m.get('avg_frame_rate') or m.get('r_frame_rate')); dur=float(m.get('duration') or 0)
    if (w,h)!=(WIDTH,HEIGHT) or abs(fr-FPS)>0.01 or dur<24: raise RuntimeError(f'Input must be 4096x2048, 60 FPS, >=24 s: {path} -> {w}x{h}, {fr}, {dur}s')
    return {'path':str(path),'sha256':sha256(path),'ffprobe':m}


def preflight(root,home,args):
    print('[1/4] Preflight: GPU, videos, head trace, and source definitions',flush=True)
    missing=[x for x in ('ffmpeg','ffprobe','cmake','c++','nvidia-smi') if shutil.which(x) is None]
    if missing: raise RuntimeError(f'Missing executables: {missing}')
    if not SATC_PY_ABS.is_file(): raise RuntimeError(f'Missing SATC Python: {SATC_PY_ABS}')
    if not SDK_ABS.is_dir(): raise RuntimeError(f'Missing NV Video Codec SDK: {SDK_ABS}')
    if shutil.disk_usage(root).free<6*1024**3: raise RuntimeError('Need at least 6 GiB free disk space')
    videos={}
    for n,p in FIXED_VIDEOS.items():
        if not p.is_file(): raise RuntimeError(f'Missing prepared input: {p}')
        videos[n]=p
    london,audit=discover_london(home,args.london_video); videos['london_tower']=london
    video_meta={n:validate_video(p) for n,p in videos.items()}
    shared,shared_meta=find_shared_mat(home,root,args.shared_mat)
    trace_csv=root/'common_head_trace_60fps.csv'; trace_meta=prepare_common_trace(shared,trace_csv,args.trace_index)
    dump(root/'london_discovery.json',audit); dump(root/'trace_selection.json',{**shared_meta,**trace_meta})
    command(['nvidia-smi','-q'],root/'gpu_before.txt'); command(['ffmpeg','-version'],root/'ffmpeg_version.txt')
    protocol={
      'version':VERSION,'scope':'uncapped local sender processing only; no WebRTC, Mininet, receiver, HMD, pacing limiter, or intentional frame drops',
      'videos':video_meta,'resolution':[WIDTH,HEIGHT],'fps':FPS,'codecs':list(CODECS),'target_mbps':list(RATES),'methods':list(METHODS),
      'encoder':{'api':'NVIDIA NVENC','preset':'p4','tuning':'low_latency','rate_control':'CBR','gop':240,'b_frames':0,'lookahead':False,'spatial_aq':False,'temporal_aq':False,'vbv_seconds':0.25},
      'benchmark':{'warmup_frames':WARMUP,'measured_frames':MEASURED,'timer_start':'after final warmup AU and before measured source gate opens','timer_end':'after final measured AU returns','retry':'one retry only on execution/integrity failure, never because FPS is low'},
      'tile_grid':[5,9],'zone_geometry':'Chebyshev rings around viewport center with horizontal ERP wrap; center position yields 1/8/16/20 tiles in Z1/Z2/Z3/Z4',
      'head_trace':trace_meta,
      'compression_mapping':'published Gamma levels 0,10,...,100 mapped one-to-one to NVENC QP deltas -5,-4,...,+5; Gamma=50 is zero delta',
      'MUC':'uniform Gamma=100%',
      'PC':'fixed Gamma=(0,30,70,100)% for Z1..Z4',
      'AUC':'minimum uniform 10%-quantized Gamma predicted to fit the per-frame target budget; size model is calibrated during warmup and updated from encoded-size feedback',
      '360ST':'four-zone Gamma action from the published 0..100%/10% action space; bandwidth-constrained action selection maximizes viewport-weighted quality using eta=(0.4,0.3,0.2,0.1); encoded-size model is calibrated during warmup',
      'sources':{'public_repo':'https://github.com/AndreaCarusoPhD/vr360encoding','head_trace_dataset':'https://albara.ramli.net/research/360/','paper_baseline_definitions':'Caruso et al., An Adaptive Closed-Loop Encoding VNF for Virtual Reality Applications, IEEE NetSoft 2024'},
    }
    dump(root/'protocol.json',protocol)
    return videos,trace_csv,protocol


def run_one(root,code,encoder,videos,trace,video_name,codec,rate,method,attempt):
    out=root/'runs'/f'{video_name}_{codec}_{rate}Mbps_{method}'/f'attempt_{attempt}'; out.mkdir(parents=True,exist_ok=True)
    env=base_env(root)
    if codec=='av1': env['SATC_AV1_ANNEXB']='0'
    cmd=[str(SATC_PY_ABS),str(code/'baseline_producer.py'),'--video',str(videos[video_name]),'--encoder',str(encoder),'--codec',codec,'--method',method,'--trace',str(trace),'--output-dir',str(out),'--target-bitrate-bps',str(rate*1_000_000),'--benchmark-frames',str(MEASURED),'--benchmark-warmup',str(WARMUP)]
    t0=time.time(); p=command(cmd,out/'console.log',env=env,check=False,timeout=300); outer=time.time()-t0
    result={'video':video_name,'codec':codec,'target_mbps':rate,'method':method,'attempt':attempt,'return_code':p.returncode,'outer_elapsed_seconds':outer,'status':'FAILED','integrity_pass':False,'fps':None}
    bj=out/'benchmark.json'
    if p.returncode==0 and bj.is_file():
        d=json.loads(bj.read_text()); result.update(d)
        ok=(d.get('measured_frames')==MEASURED and d.get('warmup_frames')==WARMUP and d.get('frame_drops')==0 and d.get('fps') is not None)
        result['integrity_pass']=bool(ok); result['status']='VALID' if ok else 'FAILED_AUDIT'
    dump(out/'result.json',result); return result


def matrix(root,code,encoder,videos,trace):
    print('\n[3/4] Running 4 videos x 3 codecs x 2 rates x 4 methods = 96 measurements',flush=True)
    final=[]; orderlog=[]
    vidnames=list(videos.keys())
    for vi,v in enumerate(vidnames):
      for ci,c in enumerate(CODECS):
        for ri,rate in enumerate(RATES):
          shift=(vi+ci+ri)%len(METHODS); order=METHODS[shift:]+METHODS[:shift]
          for method in order:
            orderlog.append({'ordinal':len(orderlog)+1,'video':v,'codec':c,'target_mbps':rate,'method':method})
            print(f"  [{len(orderlog):02d}/96] {v:14s} {c:4s} {rate:2d} Mbit/s {method:5s} ...",flush=True)
            r=run_one(root,code,encoder,videos,trace,v,c,rate,method,1)
            if r['status']!='VALID':
                print('      execution/integrity failure; retrying once ...',flush=True); time.sleep(2)
                r2=run_one(root,code,encoder,videos,trace,v,c,rate,method,2); r2['first_attempt_status']=r['status']; r=r2
            final.append(r)
            fps='N/A' if r.get('fps') is None else f"{float(r['fps']):.6f}"
            print(f"      {r['status']} | processing={fps} FPS | media={r.get('actual_media_bitrate_mbps')} Mbit/s | fit={r.get('budget_fit_fraction')}",flush=True)
            if r['status']!='VALID':
                out=root/'runs'/f'{v}_{c}_{rate}Mbps_{method}'/'attempt_2'
                print('\nFATAL: the first case failed twice. Stopping instead of wasting the remaining campaign.',file=sys.stderr,flush=True)
                for name in ('console.log','nvenc_dynamic.log'):
                    p=out/name
                    if p.is_file():
                        tail=p.read_text(encoding='utf-8',errors='replace')[-8000:]
                        print(f'\n--- {name} (tail) ---\n{tail}',file=sys.stderr,flush=True)
                raise RuntimeError(f'First repeated run failure: {v} {c} {rate} Mbit/s {method}')
    dump(root/'run_order.json',orderlog)
    fields=['video','codec','target_mbps','method','status','fps','at_least_60','elapsed_seconds','measured_frames','warmup_frames','frame_drops','actual_media_bitrate_mbps','bandwidth_sustainable_fps','budget_fit_fraction','mean_policy_map_ms','p95_policy_map_ms','mean_gamma_z1','mean_gamma_z2','mean_gamma_z3','mean_gamma_z4','unique_viewport_centers','attempt','integrity_pass','return_code']
    with (root/'CARUSO_BASELINES_SUMMARY.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore'); w.writeheader(); w.writerows(final)
    valid=[r for r in final if r.get('status')=='VALID' and r.get('fps') is not None]
    agg={}
    for method in METHODS:
      agg[method]={}
      for codec in CODECS:
        agg[method][codec]={}
        for rate in RATES:
          xs=[float(r['fps']) for r in valid if r['method']==method and r['codec']==codec and r['target_mbps']==rate]
          agg[method][codec][str(rate)]={'n':len(xs),'mean_fps':statistics.fmean(xs) if xs else None,'min_fps':min(xs) if xs else None,'max_fps':max(xs) if xs else None}
    verdict={'planned_runs':96,'valid_runs':len(valid),'all_integrity_valid':len(valid)==96,'aggregate':agg,'rows':final}
    dump(root/'CARUSO_BASELINES_VERDICT.json',verdict)
    lines=['CARUSO BASELINES — 4K60 NVENC P4','',f'Valid runs: {len(valid)} / 96','Boundary: uncapped local sender processing; 240 warmup + 1200 measured completed frames; no network/receiver/pacing.','Common real recorded head trajectory replayed identically across all four videos.','', 'video, codec, rate, method, processing FPS, actual media Mbit/s, bandwidth-fit fraction']
    for r in final: lines.append(f"{r['video']}, {r['codec']}, {r['target_mbps']}, {r['method']}, {r.get('fps')}, {r.get('actual_media_bitrate_mbps')}, {r.get('budget_fit_fraction')}")
    (root/'REPORT.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    return final


def package(root,script):
    out=Path.home()/'Downloads'/'files_to_upload'; out.mkdir(parents=True,exist_ok=True)
    z=out/f'{root.name}_UPLOAD.zip'
    with zipfile.ZipFile(z,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as f:
        for p in root.rglob('*'):
            if p.is_file(): f.write(p,p.relative_to(root.parent))
        f.write(script,Path(root.name)/script.name)
    return z


def self_test():
    with tempfile.TemporaryDirectory(prefix='caruso-baseline-selftest-') as td:
        d=Path(td); extract_payload(d)
        command([sys.executable,'-m','py_compile',str(d/'baseline_producer.py')])
        command([sys.executable,str(d/'baseline_producer.py'),'--map-self-test'])
        cpp=(d/'nvenc_dynamic.cpp').read_text()
        for t in ('NV_ENC_PRESET_P4_GUID','NV_ENC_PARAMS_RC_CBR','NV_ENC_QP_MAP_DELTA'):
            if t not in cpp: raise RuntimeError(f'native encoder token missing: {t}')
        if 'v>=-5 && v<=5' not in cpp:
            raise RuntimeError('native encoder does not accept the full -5..+5 QP-delta range required by the 11 Caruso compression levels')
        if 'v==-2 || v==0 || v==2' in cpp:
            raise RuntimeError('stale 360-SATC-only QP-delta restriction is still present')
    print('PASS: baseline producer syntax, 5x9 zone geometry, QP mapping, and frozen P4/CBR/QP-map encoder source.')
    return 0


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--self-test',action='store_true',help='run only the internal self-test and exit')
    ap.add_argument('--london-video',type=Path,default=None,help='optional exact London Tower 4096x2048 60fps path; otherwise auto-discover')
    ap.add_argument('--shared-mat',type=Path,default=None,help='optional exact shared.mat path; otherwise auto-discover shared.mat/shared*.zip')
    ap.add_argument('--trace-index',type=int,default=0,help='deterministic index into valid recorded head traces found in shared.mat; default 0')
    args=ap.parse_args()
    if args.self_test: return self_test()
    print('[0/4] Internal self-test', flush=True)
    self_test()
    if os.geteuid()==0:
        print('Run as the normal Ubuntu user, not sudo.',file=sys.stderr); return 2
    user,home=real_user_home(); stamp=_dt.datetime.now().strftime('%Y%m%d_%H%M%S')
    root=home/'Downloads'/f'CARUSO_BASELINES_4VIDEOS_P4_{stamp}'; root.mkdir(parents=True,exist_ok=False)
    code=root/'code'; code.mkdir(); extract_payload(code)
    print(f'RESULTS: {root}',flush=True)
    rows=[]; upload=None
    try:
        videos,trace,protocol=preflight(root,home,args)
        print('\n[2/4] Building frozen NVENC P4 bridge',flush=True); encoder=build_encoder(root,code); print(f'  PASS: {encoder}',flush=True)
        rows=matrix(root,code,encoder,videos,trace)
        command(['nvidia-smi','-q'],root/'gpu_after.txt')
    except KeyboardInterrupt:
        (root/'INTERRUPTED.txt').write_text('Interrupted by user; completed runs preserved.\n',encoding='utf-8')
        print('Interrupted; completed runs preserved.',file=sys.stderr)
    except BaseException:
        (root/'ERROR.txt').write_text(traceback.format_exc(),encoding='utf-8'); print(traceback.format_exc(),file=sys.stderr,flush=True)
    finally:
        print('\n[4/4] Packaging',flush=True)
        try:
            upload=package(root,Path(__file__).resolve()); print(f'UPLOAD THIS FILE: {upload}',flush=True)
        except Exception: print('Packaging failed:\n'+traceback.format_exc(),file=sys.stderr)
    valid=sum(r.get('status')=='VALID' for r in rows)
    print(f'Completed valid baseline runs: {valid} / 96',flush=True)
    return 0 if valid==96 else 2

if __name__=='__main__': raise SystemExit(main())
